interface MuxUICollectionItem {
  id?: string;
  key?: string;
  label?: React.ReactNode;
  value?: string;
  textValue?: string;
  disabled?: boolean;
  [key: string]: unknown;
}

type MuxUIAccessibleName = {
  label: Exclude<React.ReactNode, null | undefined | boolean>;
  'aria-label'?: never;
  'aria-labelledby'?: never;
} | {
  label?: never;
  'aria-label': string;
  'aria-labelledby'?: never;
} | {
  label?: never;
  'aria-label'?: never;
  'aria-labelledby': string;
};

type TagGroupOwnProps = {
  label?: Exclude<React.ReactNode, null | undefined | boolean>;
  items?: (TagGroupItem | string)[];
  variant?: TagGroupVariant;
  color?: TagGroupColor;
  selectionMode?: 'none' | 'single' | 'multiple';
  selectedKeys?: Set<string>;
  defaultSelectedKeys?: Set<string>;
  onSelectionChange?: (keys: Set<string>) => void;
  disabled?: boolean;
  onRemove?: (items: TagGroupItem[]) => void;
  onAction?: (item?: TagGroupItem) => void;
};

type TagGroupProps = Omit<TagGroupOwnProps, 'label'> & {
  className?: string;
} & MuxUIAccessibleName;
